mapper.select:
select a.*
from contract_base_info a

    and a.client_id=#{dto.clientId}
    and a.proj_name like CONCAT('%',#{dto.projName},'%')
    and a.contract_code like
        CONCAT('%',#{dto.contractCode}, '%')

    and a.biz_type = #{dto.bizType}
    and a.biz_dept_id=#{dto.bizDeptId}
    and a.proj_sponsor_user_id=#{dto.projSponsorUserId}

        and json_contains(a.proj_cosponsor_user_ids, CONVERT(#{dto.projCosponsorUserId},CHAR))

    and a.contract_status=#{dto.contractStatus}

        and a.contract_status IN

            #{item}


    and a.contract_process_status=#{dto.contractProcessStatus}
    and a.payment_plan_amount >= #{dto.planedPaidAmountFrom}
    and a.payment_plan_amount <= #{dto.planedPaidAmountTo}
    and a.payment_plan_date >= #{dto.planedPaidDateFrom}
    and a.payment_plan_date <= #{dto.planedPaidDateTo}
    and a.create_time >= #{dto.createFrom}
    and a.create_time <= #{dto.createTo}
    and a.update_time >= #{dto.updateFrom}
    and a.update_time <= #{dto.updateTo}


order by update_time desc

select a.*
