select a.contract_id, max(b.cash_flow_date) cashFlowDate from ( select contract_id , receipt_id, max(cash_flow_phase) phase from (SELECT p.* FROM contract_rent_actual_lib p INNER JOIN (SELECT main_id AS contract_id, MAX(version) AS version FROM common_version t1 WHERE t1.module = 'CONTRACT' AND t1.version_type = 1 GROUP BY main_id) m ON p.contract_id = m.contract_id AND p.version = m.version) c where contract_id in
#{item}
group by contract_id,receipt_id ) a left join (SELECT p.* FROM contract_rent_actual_lib p INNER JOIN (SELECT main_id AS contract_id, MAX(version) AS version FROM common_version t1 WHERE t1.module = 'CONTRACT' AND t1.version_type = 1 GROUP BY main_id) m ON p.contract_id = m.contract_id AND p.version = m.version) b on a.contract_id = b.contract_id and a.receipt_id = b.receipt_id and a.phase = b.cash_flow_phase where cash_flow_date >= #{dto.timeFrom} and cash_flow_date <= #{dto.timeTo} and a.receipt_id in
#{item}
group by a.contract_id

select contract_id , max(cash_flow_date) cashFlowDate from (SELECT p.* FROM contract_rent_actual_lib p INNER JOIN (SELECT main_id AS contract_id, MAX(version) AS version FROM common_version t1 WHERE t1.module = 'CONTRACT' AND t1.version_type = 1 GROUP BY main_id) m ON p.contract_id = m.contract_id AND p.version = m.version) c where contract_id in
#{item}
group by contract_id

SELECT a.client_id, max( a.lease_month_count ) AS lease_month_count FROM ( SELECT b.client_id, IFNULL(( SELECT lease_month_count FROM contract_lease_price WHERE contract_id = b.id ), 0 ) AS lease_month_count FROM contract_base_info b WHERE b.id IN
#{item}
UNION ALL SELECT b.client_id, IFNULL(( SELECT aoc_credit_term FROM contract_aoc_price WHERE contract_id = b.id ), 0 ) AS lease_month_count FROM contract_base_info b WHERE b.id IN
#{item}
UNION ALL SELECT b.client_id, IFNULL(( SELECT factoring_credit_term FROM contract_factoring_price b WHERE contract_id = b.id ), 0 ) AS lease_month_count FROM contract_base_info b WHERE b.id IN
#{item}
) a GROUP BY a.client_id

select contract_id, max(cash_flow_date) endTime from contract_rent_actual where contract_id in
#{item}
group by contract_id

select a.id, a.contract_code as contractCode, b.lessee_id as lesseeId, b.lessee_name as lesseeName, b.lessee_type as lesseeType, c.detail as address, d.lateCharge, d.overdueAmount as overdueAmount, d.overdueDays as overdueDays, d.phases as phases, u.user_name as projectSponsorName, u.phone as projectSponsorPhone from contract_base_info a left join contract_tenantry b on a.id = b.contract_id left join corp_address_info c on c.address_type = 'WORK_ADDRESS' and b.lessee_id = c.client_id left join (select contract_id as contractId, client_id as clientId, max(a.overdue_days) as overdueDays, sum(a.overdue_amount) as overdueAmount, sum(a.lateCharge) as lateCharge, group_concat(',',a.phase) as phases from ( select id, client_id, contract_id, if (ifnull(plan_collection_amount,0) > ifnull(collection_amount,0), phase, null) as phase, (if(isnull(plan_collection_amount), 0, plan_collection_amount) - if(isnull(collection_amount), 0, collection_amount)) as overdue_amount, (if(isnull(penalty_interest), 0, penalty_interest) - if(isnull(collection_penalty_interest), 0, collection_penalty_interest)) as lateCharge, if (ifnull(plan_collection_amount,0) > ifnull(collection_amount,0), TIMESTAMPDIFF(DAY,plan_collection_date, DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%S')), 0) as overdue_days from collection_base_info where write_off_status != 'WRITE_OFF_COMPLETED' and cash_flow_item = 'RENT' AND plan_collection_date < CURRENT_DATE ) a group by contractId) d on d.contractId = a.id left join bifrost_user u on u.id = a.proj_sponsor_user_id where a.id in
#{item}
order by id, b.lessee_type desc

select a.id, a.contract_code as contractCode, b.lessee_id as lesseeId, b.lessee_name as lesseeName, b.lessee_type as lesseeType, c.detail as address, d.lateCharge, d.overdueAmount as overdueAmount, d.overdueDays as overdueDays, d.phases as phases, u.user_name as projectSponsorName, u.phone as projectSponsorPhone, d.collectionId as collectionId from contract_base_info a left join contract_tenantry b on a.id = b.contract_id left join corp_address_info c on c.address_type = 'WORK_ADDRESS' and b.lessee_id = c.client_id left join (select contract_id as contractId, client_id as clientId, max(a.overdue_days) as overdueDays, sum(a.overdue_amount) as overdueAmount, sum(a.lateCharge) as lateCharge, group_concat(',',a.phase) as phases, a.id as collectionId from ( select id, client_id, contract_id, if (ifnull(plan_collection_amount,0) > ifnull(collection_amount,0), phase, null) as phase, (if(isnull(plan_collection_amount), 0, plan_collection_amount) - if(isnull(collection_amount), 0, collection_amount)) as overdue_amount, (if(isnull(penalty_interest), 0, penalty_interest) - if(isnull(collection_penalty_interest), 0, collection_penalty_interest)) as lateCharge, if (ifnull(plan_collection_amount,0) > ifnull(collection_amount,0), TIMESTAMPDIFF(DAY,plan_collection_date, DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%S')), 0) as overdue_days from collection_base_info where write_off_status != 'WRITE_OFF_COMPLETED' and cash_flow_item = 'RENT' AND plan_collection_date < CURRENT_DATE ) a group by contractId,id) d on d.contractId = a.id left join bifrost_user u on u.id = a.proj_sponsor_user_id where a.id in
#{item}
order by id, b.lessee_type desc

SELECT p.contract_id as contractId,p.guarantor_ids as clientId, 'guarantor' as role FROM contract_guarantor_lib p INNER JOIN (SELECT main_id AS contract_id, MAX(version) AS version FROM common_version t1 WHERE t1.module = 'CONTRACT' AND t1.version_type = 1 GROUP BY main_id) m ON p.contract_id = m.contract_id AND p.version = m.version where p.contract_id in
#{item}
union all SELECT p.contract_id as contractId,p.lessee_id as clientId,'lessee' as role FROM contract_tenantry_lib p INNER JOIN (SELECT main_id AS contract_id, MAX(version) AS version FROM common_version t1 WHERE t1.module = 'CONTRACT' AND t1.version_type = 1 GROUP BY main_id) m ON p.contract_id = m.contract_id AND p.version = m.version where p.contract_id in
#{item}
